(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["uz"] = {"ui":{"skip":"Mazmunga oʻtish","back":"← AI-gile’ga qaytish","lang.button":"Til: {name}","lang.dialog":"Tilni tanlang","lang.search":"Til qidirish","lang.none":"Mos til topilmadi","lang.notYet":"{name} hali tarjima qilinmagan","theme.aria":"Mavzuni almashtirish: yorugʻ, qorongʻi yoki qora","theme.toLight":"Yorugʻ mavzuga oʻtish","theme.toDark":"Qorongʻi mavzuga oʻtish","theme.toBlack":"Qora mavzuga oʻtish (haqiqiy qora, OLED ekranlar uchun qulay)","words.underline":"Sahifadagi bu soʻzlarning tagiga chizish","words.underlineHelp":"Maʼnosini koʻrish uchun nuqtali soʻz ustiga sichqonchani olib boring yoki unga bosing.","index.title":"AI-gile: sun’iy intellektli dasturchilar jamoangiz, bitta doskada","index.description":"AI-gile — sun’iy intellekt bilan kod yozadigan jamoalar uchun kanban doskasi. Siz uxlab yotganingizda ular ishlaydi; sizga esa qaror qilish, sinash va qabul qilish uchun bitta qisqa toʻplam qoladi.","hero.logoAlt":"AI-gile doskasi belgisi","hero.h1.html":"Sun’iy intellektli dasturchilar jamoangiz, bitta&nbsp;doskada.","hero.alpha":"🐣 Yopiq pre-alfa","hero.alphaTitle":"Hali erta va tugallanmagan: sinab koʻrganingiz uchun rahmat!","hero.lede":"Ular siz uxlayotganda ishlaydi. Ertalab sizni qisqa bir toʻplam kutadi: bir nechta savol, sinab koʻriladigan bir-ikki narsa, bitta-ikkita binafsha olmos. Bosing, qabul qiling, qahvangizga qayting.","dl.windows":"Windows ilovasi","dl.browser":"Brauzerda ishga tushirish","dl.messenger":"📱 Telefoningiz uchun Messenger","dl.soon":"Tez orada","dl.notify":"🔔 Ochilganda xabar bering","dl.notifySmall":"Alfa yoki beta","hero.secondary":"Agile, lekin jamoaga hech qachon stend-ap qahvasi kerak emas. (Baribir stend-ap oʻtkazishadi.)","pitch.h2":"AI-gile siz xohlagancha soʻzda","pitch.lede":"Uzunlikni tanlang: bir soʻzdan 144 gacha. Har bir uzunlik oʻz oʻlchamiga moslab yozilgan alohida tavsif. Sirpanchni suring yoki strelka tugmalaridan foydalaning.","pitch.rangeLabel":"Uzunlik soʻzlarda","pitch.dice":"🎲 boshqa variant","pitch.words.one":"{n} soʻz","pitch.words.other":"{n} soʻz","pitch.letters.one":"{n} harf","pitch.letters.other":"{n} harf","pitch.chars.one":"{n} belgi","pitch.chars.other":"{n} belgi","count.line.html.one":"Hozir doskada {n} karta bor","count.line.html.other":"Hozir doskada {n} karta bor","features.aria":"U nima qiladi","f.pile.h":"Siz uchun bitta toʻplam","f.pile.html":"<b>Siz uchun</b> barcha loyihalarda sizni kutayotgan hamma narsani yigʻadi: savollar, sinab koʻriladigan narsalar, faqat odam qila oladigan ishlar. Navbatingiz keyingisi nima ekanini va qancha vaqt olishini aytadi.","f.sleep.h":"Siz uxlaganingizda ishlaydigan jamoalar","f.sleep.p":"Har bir loyihaning rahbari va sun’iy intellekt agentlaridan iborat jamoasi bor. Kartaga izoh yozing, jamoa uygʻonadi, ishni bajaradi va charchagan odam ham kuzata oladigan qadamlar bilan qaytaradi.","f.tester.h":"Avval sun’iy intellekt tekshiruvchisi koʻradi","f.tester.p":"Sizga biror narsa yetib kelmasidan oldin tekshiruvchi ilovaning nusxasida qadamlarni bajaradi va nimani koʻrganini skrinshot bilan koʻrsatadi. Oʻtganlarini varaqlab chiqing va bir bosishda qabul qiling.","f.proof.h":"Va’da emas, dalil","f.proof.p":"Har bir topshirish nima oʻzgarganini koʻrsatadi: fayllarni, farqni, skrinshotlarni. Tayyor boʻldimi, deb har bir ilovani ochib chiqish shart emas.","f.chat.h":"Rahbarlaringiz bilan suhbatlashing","f.chat.p":"Discord uslubidagi yon panel: har bir loyiha uchun bitta belgi, sizga kerak joyda binafsha olmoslar. Rahbarga gʻoyani yozing; u uni kartalar va rejaga aylantiradi, yonida ✅ Boshlash tugmasi bilan.","f.tidy.h":"Oʻzi tartibni saqlaydi","f.tidy.p":"Bogʻliq kartalar bittaga birlashadi, chalkash sarlavhalar tuzatiladi, token tekshiruvi esa kodni yengil saqlaydi. Almashtiriladigan narsa kam, oʻylanadigan narsa kam.","f.private.h":"Sizniki, sizning kompyuteringizda","f.private.li1":"Doska oʻz kompyuteringizda ishlaydi va faqat sizga javob beradi.","f.private.li2":"Odamlar orasidagi shaxsiy xabarlar boshidan oxirigacha shifrlangan.","f.private.li3":"Akkauntlar yoʻq, kuzatuvchilar yoʻq, kukilar yoʻq.","f.lang.h":"Oʻz tilingizda","f.lang.p":"Golland, uels va yapon tillaridan tortib qaroqchi, Yoda va klingon tillarigacha 120 dan ortiq til, kasbiy atamalar uchun inglizchaga tez qaytish tugmasi bilan.","f.service.h":"Gʻoyadan haqiqiy xizmatgacha","f.service.p":"AI bilan nimadir yaratdingizmi va undan endi odamlar foydalanyaptimi? Uni xizmat deb belgilang, doska uni yaxshi yuritishga yordam beradi: ishlashni tekshirish, ochiq holat sahifasi, tahlili yozilgan hodisalar, Go talab qiladigan oʻzgarishlar, har kuni tekshiriladigan zaxira nusxalar. Yordam har bir qadamni yoʻl-yoʻlakay oʻrgatadi.","msgr.h2":"AI-gile Messenger: jamoangiz choʻntagingizda","msgr.p1":"Doskani ochmasdan AI jamoangiz bilan gaplashing. Loyiha rahbarlaringiz va doʻstlaringiz bilan chatlashing, kartaning test qadamlarini koʻring va ularga javob bering, hammasi telefoningizdan.","msgr.p2":"Ulash uchun doskangizdagi QR kodni skanerlang. Birinchi martami? Samimiy demo chat sizga hammasini koʻrsatib beradi.","msgr.when":"Avval Android, keyin telefonlar va iPhone uchun veb-versiya.","msgr.who":"Loyiha rahbaringiz","msgr.b1":"Tungi rejim tuzatmasi tayyor. Test qadamlarini yuboraymi?","msgr.b2":"Ha, iltimos!","msgr.b3":"1. Sozlamalarni oching. 2. Tungi rejimni tanlang. Toʻgʻri koʻrinyaptimi?","tl.aria":"Birinchi suhbatdan yoʻl xaritasigacha boʻlgan vaqt chizigʻi","tl.h2":"Birinchi suhbatdan keyingi qadamgacha","tl.lede":"Haqiqiy sanalar va vaqtlar, oʻz vaqt mintaqangizda. Bugundan keyingisi — reja, sana va’da qilinmaydi.","tl.today":"Bugun","tl.planned":"rejalashtirilgan","tl.cards.one":"{n} karta","tl.cards.other":"{n} karta","join.h2":"Qoʻshiling","join.lede":"AI-gile’ni bitta kichkina odam va juda koʻp sabrli agentlar yaratmoqda. Hozircha u yopiq, doʻstlar bilan yopiq alfada. Ochilganda sinab koʻrmoqchimisiz?","join.btn":"Qiziqishimni qayd etish","join.small":"Sizga email yozamiz, boshqa hech narsa yoʻq","footer.tag":"AI-gile. Kuzatuvchilarsiz, kukilarsiz, stend-ap qahvasiz.","footer.licence":"Biznes litsenziyasi","footer.status":"Holat","footer.privacy":"Nimalarni saqlaymiz","footer.thanks":"Qoʻngʻiroqlar ChilledChat tufayli","form.sending":"Yuborilmoqda…","form.failed":"Boʻlmadi: keyinroq qayta urinib koʻring.","form.offline":"AI-gile bilan aloqa oʻrnatib boʻlmadi: keyinroq qayta urinib koʻring.","form.keep":"Bundan faqat sizga javob berish uchun foydalanamiz, keyin oʻchirib tashlaymiz. Kuzatuvchilar yoʻq, kukilar yoʻq.","form.keepLink":"Nimalarni saqlaymiz","interest.title":"AI-gile: alfa ochilganda xabar bering","interest.description":"AI-gile’ning yopiq alfasi yoki betasi ochilganda xabar topish uchun emailingizni qoldiring.","interest.h1":"🔔 Ochilganda xabar bering","interest.lede":"AI-gile yopiq pre-alfada. Emailingizni qoldiring, sizga joy topilganda bir marta yozamiz.","interest.email":"Emailingiz","interest.which":"Qaysi sinov?","interest.alpha":"Yopiq alfa: erta, dagʻal, koʻp oʻzgarishlar","interest.beta":"Beta: barqarorroq, keyinroq","interest.both":"Qaysi biri avval chiqsa, farqi yoʻq","interest.submit":"Meni roʻyxatga yozing","interest.thanks":"Rahmat! Siz roʻyxatdasiz.","licence.title":"AI-gile: biznes litsenziyasi","licence.description":"AI-gile’dan biznesingizda foydalanasizmi? Bepul biznes litsenziyasiga ariza bering.","licence.h1":"📜 Biznes litsenziyasi","licence.lede":"AI-gile’dan ishda foydalanasizmi? Kimligingiz va nima bilan shugʻullanishingizni yozing. Agar bu biroz yaxshilik qilsa, litsenziya bepul.","licence.company":"Kompaniya","licence.website":"Veb-sayt","licence.what":"Nima bilan shugʻullanasiz","licence.how":"Bu dunyoga qanday yordam beradi","licence.email":"Email","licence.submit":"Ariza berish","licence.thanks":"Rahmat! Email orqali javob beramiz.","status.title":"AI-gile holati","status.h1":"AI-gile holati","status.quiet":"Hammasi tinch","status.intro":"AI-gile hozir ishlayaptimi? Bu sahifa har 5 daqiqada veb-sayt, doska ulashish, qoʻngʻiroqlar va yuklab olishni tekshiradi.","status.up":"Ishlayapti ({ms} ms da javob berdi)","status.slow":"Oxirgi tekshiruvga javob bermadi, qayta urinilmoqda","status.down":"Ishlamayapti: oxirgi ikki tekshiruvga javob bermadi","status.svc.web":"Veb-sayt","status.svc.web.offers":"Shu sayt: AI-gile nima ekanligi va qiziqish formasi","status.svc.boards":"Doska ulashish","status.svc.boards.offers":"Ommaviy doskalar, doʻstlar orasidagi xabarlar va taklifnomalar","status.svc.calls":"Qoʻngʻiroqlar","status.svc.calls.offers":"AI-gile ichida ovozli va video qoʻngʻiroqlar, ekranni ulashish","status.svc.download":"Yuklab olish","status.svc.download.offers":"Windows oʻrnatuvchisi va taklif havolalari","status.checking":"Tekshirilmoqda…","status.offline":"Holat xizmatiga hozir ulanib boʻlmayapti (qayta urinilmoqda)","status.updated":"yangilandi: {ago}","status.justNow":"hozirgina","status.min":"{n} daqiqa oldin","status.hours":"{n} soat oldin","status.days":"{n} kun oldin","privacy.title":"AI-gile: nimalarni saqlaymiz","privacy.h1":"Nimalarni saqlaymiz","privacy.lede":"Qisqasi: faqat siz yuborgan narsa, u ham uzoq vaqtga emas.","privacy.only":"Faqat siz bizga yuborgan narsa: formaga yozganingiz, masalan emailingiz. Siz haqingizda boshqa hech narsa.","privacy.sealed":"U muhrlanadi, shuning uchun serverimiz uni oʻqiy olmaydi: brauzeringizda, joʻnab ketishidan oldin (eskiroq brauzerda esa yetib kelgan zahoti). Uni faqat oʻzimizning doskamiz ocha oladi.","privacy.server":"Doskamizga yetib borishi bilan serverdan oʻchiriladi. 30 kundan keyin ham u yerda qolgan har qanday narsa baribir oʻchiriladi.","privacy.board":"Uni doskamizda faqat sizga javob berguncha saqlaymiz, keyin u yerdan ham oʻchiramiz.","privacy.none":"Kuzatuvchilar yoʻq, kukilar yoʻq, analitika yoʻq.","privacy.local":"Tilingiz va yorugʻ yoki qorongʻi mavzu tanlovingiz oʻz brauzeringizda qoladi. Ular hech qachon bizga yuborilmaydi.","privacy.ask":"Tezroq oʻchirilishini xohlaysizmi? Xatimizga javob yozib, shuni ayting.","live.h2":"Uning qurilishini jonli kuzating","live.caption":"Har bir karta yashirilgan: siz ishning shaklini ko'rasiz, so'zlarni emas.","live.watching.one":"jonli: {n} kuzatmoqda","live.watching.other":"jonli: {n} kuzatmoqda","live.last.now":"Oxirgi karta hozirgina koʻchirildi","live.last.min.one":"Oxirgi karta {n} daqiqa oldin koʻchirildi","live.last.min.other":"Oxirgi karta {n} daqiqa oldin koʻchirildi","live.last.hour.one":"Oxirgi karta {n} soat oldin koʻchirildi","live.last.hour.other":"Oxirgi karta {n} soat oldin koʻchirildi","live.last.day.one":"Oxirgi karta {n} kun oldin koʻchirildi","live.last.day.other":"Oxirgi karta {n} kun oldin koʻchirildi","live.offline":"Jonli taxta biroz dam olyapti. Tez orada yana kiring.","live.cols":"Backlog|Bajarilishi kerak|Jarayonda|Jamoa tekshirmoqda|Siz test qilishingiz kerak|Jamoa uchun|Bajarildi"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robotlar.","Topshirildi."]},{"n":2,"texts":["Robotlar kanbani.","Agentlar, tartibda.","Gʻoyalar, bajarildi."]},{"n":3,"texts":["Robotlar uchun kanban.","Gʻoyalar funksiyaga aylanadi.","Bepul agent kanbani."]},{"n":5,"texts":["Agentlar yuritadigan kanban doskasi.","Siz karta yozasiz. Agentlar quradi.","Bepul, mahalliy, sinalgan, biroz kulgili."]},{"n":8,"texts":["Sun’iy intellekt agentlari ishlaydigan bepul kanban doskasi.","Gʻoyani yozing. Agentlar quradi. Siz qabul qilasiz.","Bitta odam va koʻp sabrli robotlar uchun agile."]},{"n":13,"texts":["Kompyuteringizdagi kanban doskasi: kartalarni olib ishlaydiganlar esa sun’iy intellekt agentlari.","Gʻoya yozing. Agentlar jamoasi uni quradi. Tekshiruvchi esa sinab koʻradi.","Bepul, akkauntlarsiz, kuzatuvchilarsiz: bitta doska, bir nechta robot va hamma narsaga siz rahbar."]},{"n":21,"texts":["AI-gile — sun’iy intellekt dasturchi agentlari bilan ishlash uchun kanban doskasi. Kartalarni ular olib ishlaydi; siz esa ularni sinab koʻrasiz va qabul qilasiz.","Har bir loyihaning bitta rahbari va sun’iy intellekt agentlaridan iborat jamoasi bor. Istalgan kartaga izoh yozing, jamoa darhol ishga kirishadi.","Oʻz kompyuteringizda ishlaydigan bepul va shaxsiy vazifalar doskasi. Ishlaydiganlar — robotlar. Oxirida «ha» deydigan esa faqat siz, hamma vaqt."]},{"n":34,"texts":["Siz gʻoyalarni doskaga qoʻyasiz. Sun’iy intellekt agentlaridan iborat jamoa ularni ishlaydigan funksiyalarga aylantiradi, sinab koʻradi va sinab koʻrish uchun qadamlar bilan sizga qaytaradi. Siz aytmaguningizcha hech narsa tayyor hisoblanmaydi.","AI-gile — Rich hozir oʻzi boshqaradigan agentlarning katta yordami bilan uyda yasagan kanban doskasi. U bepul, sizning kompyuteringizda ishlaydi va sotilmaydi, balki shunchaki doʻstlar bilan ulashiladi, hech kimdan pul soʻralmaydi.","Oddiy kanban doskasini tasavvur qiling: ustunlar Backlogdan Bajarildigacha, faqat kartalarni sun’iy intellekt agentlari olib ishlaydi. Ular yutuqlar haqida xabar beradi, tiqilib qolsa soʻraydi va doimo sizning roziligingizni kutadi."]},{"n":55,"texts":["AI-gile — jamoasi sun’iy intellekt agentlaridan iborat kanban doskasi. Har bir loyihada ishni rejalashtiradigan rahbar va uni bajaradigan yordamchilar bor. Funksiya tayyor boʻlganda sun’iy intellekt tekshiruvchisi uni sinab koʻradi va skrinshot oladi, keyin u sizning toʻplamingizga tushadi. Qabul qiling yoki izoh yozing, ular qayta ishlaydi.","Bu bir kishi bir vaqtda koʻplab sun’iy intellekt kod yozish seanslarini kuzatib borish yoʻli sifatida boshlandi va chinakam doskaga aylandi. U sizning kompyuteringizda ishlaydi, akkaunt talab qilmaydi va kuzatuvchilari yoʻq. Doʻstlar va qiziquvchilar uchun bepul. U hali tugallanmagan ham, shuning uchun dagʻalliklar va goho kutilmagan holatlarni kuting.","Mana, halol variant. Gʻoyalarni baribir siz oʻylab topasiz, natijalarni ham baribir siz tekshirasiz. AI-gile esa oraliqdagi hamma narsani qiladi: kartalarni tartibda saqlaydi, siz izoh yozganingizda kerakli agentni uygʻotadi, aynan nima oʻzgarganini koʻrsatadi va hammasini faqat siz uchun bitta qisqa toʻplamga yigʻadi. Boshqa hech narsa shart emas."]},{"n":89,"texts":["AI-gile — oʻz kompyuteringizda ishga tushiradigan bepul kanban doskasi. Har bir loyihada odamlar oʻrniga sun’iy intellekt agentlaridan iborat jamoa bor: gʻoyalaringizni kartalar va rejaga aylantiradigan rahbar hamda kartalarni ustuvorlik tartibida oladigan yordamchilar. Biror narsa qurib boʻlinganda sun’iy intellekt tekshiruvchisi sinov qadamlarini bajaradi va nimani koʻrganini sizga koʻrsatadi. Keyin u «Siz uchun» deb nomlangan bitta toʻplamda kutadi. Siz qabul qilasiz yoki izoh yozasiz, jamoa esa yana urinib koʻradi. Siz boʻlmasangiz, hech narsa «Bajarildi»ga yetmaydi.","Kutilmagan ba’zi imkoniyatlar ham bor. Tungi qorovul siz uxlaganingizda «Bajarilishi kerak» ustunini toʻldirib turadi va sizdan javob talab qilmaydigan kartalarni tanlaydi. Token hisoblagichi agentlar bugun va shu hafta qancha sarflaganini koʻrsatadi, «Tokensiz rejim» esa ularga sarflashni toʻxtatishni buyuradi. Doʻstlaringizga xabar yozishingiz mumkin, shaxsiy xabarlar esa boshidan oxirigacha shifrlangan. Doska taxminan 120 tilda gapiradi, jumladan golland, flamand, qaroqchi va klingon tillarida. Bularning hech biri bir tiyin turmaydi, hech kim sizga biror narsa sotmoqchi ham emas.","AI-gile — kichik, shaxsiy loyiha, kompaniya emas. Rich bir nechta sun’iy intellektli kod loyihasini har bir ilovani alohida ochmasdan kuzatib borishni xohladi, shuning uchun agentlar bilan birga buning uchun doska yasadi, keyin esa qolgan qismini ham oʻsha doska bilan qurdi. U hozir yopiq pre-alfada, ya’ni bir hovuch doʻstlar uchun asosan ishlaydi. Narxlar sahifasi yoʻq, axborot byulleteni yoʻq, oʻsish rejasi ham yoʻq. Agar bularning hammasi foydali tuyulsa, u bir oz kengroq ochilganda sinab koʻrishni soʻrashingiz mumkin."]},{"n":144,"texts":["AI-gile — bitta odam va koʻplab sun’iy intellekt agentlari uchun kanban doskasi. U oʻz kompyuteringizda ishlaydi va butunlay bepul. Siz loyihalar qoʻshasiz, har bir loyiha esa oʻz rahbari va kichik jamoasini oladi. Rahbar bilan Discord’dagiga oʻxshab suhbatlashasiz va gʻoyani tasvirlab berasiz; rahbar uni kartalar va rejaga aylantiradi, keyin «Boshlash» tugmasini bosishingizni kutadi. Jamoa kartalarni ustuvorlik tartibida birma-bir ishlab chiqadi, buning uchun til modellari uchun yasalgan oddiy buyruq qatoridan foydalanadi. Biror narsa sizga qaytishidan oldin sun’iy intellekt tekshiruvchisi ilovaning nusxasida barcha qadamlarni bajaradi va skrinshot biriktiradi. Tayyor ish oʻzgargan fayllar va farq bilan sizning toʻplamingizga tushadi. Siz uni qabul qilasiz yoki izoh qoldirasiz, jamoa esa uygʻonib, qayta urinib koʻradi. Kartani «Bajarildi» ustuniga faqat siz va faqat oʻzingiz koʻchira olasiz.","AI-gile bilan taxminan bir kun shunday oʻtadi. Kechqurun bir nechta izoh qoldirasiz: bu tugma notoʻgʻri joyda turibdi, u roʻyxatni saralash kerak, qorongʻi mavzu boʻlsa-chi. Siz uxlashga ketasiz. Agentlar izohlarni oʻqiydi, oʻzgartirishlarni qiladi, hammasini sinab koʻradi va sizga qaytaradi. «Bajarilishi kerak» boʻshab qolsa, tungi qorovul uni backlogdan sizdan javob talab qilmaydigan kartalar bilan toʻldiradi. Ertalab bitta qisqa toʻplam kutadi: bir nechta savol va sinab koʻriladigan bir nechta narsa, har biri uyqusirab turgan odam ham bajara oladigan qadamlar va ishlayotganini koʻrsatadigan skrinshot bilan. Siz birma-bir bosib chiqasiz, yaxshilarini qabul qilasiz, qolganlarini qaytarasiz. Token hisoblagichi bularning hammasi qancha sarflaganini koʻrsatadi, «Tokensiz rejim» esa tejamkor haftalar uchun tayyor turadi. Keyin nonushta qilasiz, bunda agentlar hozircha afsuski yordam bera olmaydi.","Avval AI-gile nima emasligi haqida. U startap emas, sotuvga qoʻyilmagan va hech kim maʼlumotlaringizni yigʻmaydi. U kompyuteringizda ishlaydigan, akkauntsiz, kuzatuvchisiz va kukisiz bepul doska. U nima esa: barcha sun’iy intellektli kod loyihalarini bir vaqtda koʻrish uchun yagona saranjom joy, bunda kartalarni agentlar jamoasi bajaradi, qarorlarni esa siz qabul qilasiz. U bogʻliq kartalarni birlashtiradi, chalkash sarlavhalarni tuzatadi va kod qanchalik yengil qolayotganini kuzatib turadi. U taxminan 120 tilda gapiradi, golland va flamand tillaridan tortib qaroqchi va klingon tillarigacha. Doʻstlar bir-biriga shaxsiy va shifrlangan xabar yozishi mumkin. Uni Rich va juda koʻp sabrli agentlar yaratdi, asosan oʻzidan oʻzi foydalanib. U hozir yopiq pre-alfada, shuning uchun ba’zi joylari dagʻal. Qiziq tuyulsa, yaxshilab soʻrang, balki boshqalardan erta kirib qolarsiz."]}],"quips":{"1":"Bitta soʻz. Jasur. Balki juda jasur.","3":"Uchta soʻz. Allaqachon koʻp mahsulot sahifalaridan halolroq.","8":"Sakkizta soʻz. Baribir bitta stend-apdan qisqa.","21":"Aytgancha, uzunliklar story point’lar. Albatta-da.","55":"Ellik beshta soʻz. Siz oʻqiguncha ikkita karta tugadi.","144":"Bu eng uzuni. 233 yoʻq. Agentlar uxlashga ketdi."}},"timeline":{"first-idea.name":"Birinchi gʻoya","first-idea.line":"Hali bitta qator kod boʻlmagan paytdagi eng birinchi suhbat.","first-board.name":"Birinchi doska","first-board.line":"Oʻz yaratilishini kuzatib boradigan doska: kartalar, ustunlar, sudrab tashlash, loyihalar.","team-roles.name":"Jamoa va rollar","team-roles.line":"Agent profillari, jamoa shablonlari, maydonlar va kim nima qilishi.","install.name":"Oʻrnatish va relizlar","install.line":"Doʻst oʻrnata oladigan zip, oʻz-oʻzidan yangilanish, kanallar va ortga qaytarish.","usage-saver.name":"Sarfni tejash","usage-saver.line":"Ishga tushirishlar narxini oʻlchash, kodni yengil saqlash, limitingizni asrash.","friends.name":"Doʻstlar va ulashish","friends.line":"Shaxsiy xabarlar, aralashtirilgan uzatgich, takliflar, rollar va umumiy loyihalar.","languages.name":"Tillar","languages.line":"Ekrandagi har bir matn til faylida, avval golland va flamand tillari.","ai-tester.name":"Sun’iy intellekt tekshiruvchisi","ai-tester.line":"Tekshiruvchi har bir topshirishni avval koʻrib chiqadi va nimani koʻrganini koʻrsatadi.","website.name":"Veb-sayt","website.line":"aigile.lol, tizer va shu vaqt chizigʻi.","streaming.name":"Chat va strimlar","streaming.line":"Discord, Twitch, OBS, strimer rejimi, GIFlar va emojilar.","no-ai.name":"Sun’iy intellektsiz nashr","no-ai.line":"Sun’iy intellektsiz kod yozadiganlar uchun doska va ochiq doskalar.","night-watch.name":"Tungi qorovul","night-watch.line":"Qorovul va Scrum Master siz uxlaganingizda jamoalarni ish ustida ushlab turadi.","p-more.name":"Qolgan hamma narsa","p-more.line":"Navbatini kutayotgan kichikroq gʻoyalar.","p-android.name":"Telefon va Android","p-android.line":"Doskangizga telefondan kirish, keyin esa mahalliy Android ilovasi.","p-release.name":"Alfa va undan keyin","p-release.line":"Yopiq alfa, jonli sayt, keyin beta.","p-languages.name":"Koʻproq tillar","p-languages.line":"Yuzdan ortiq til va til oʻrganuvchilar uchun immersiya rejimi.","p-engines.name":"Koʻproq sun’iy intellekt dvigatellari","p-engines.line":"Har bir agent uchun Claude, Codex yoki Gemini’ni tanlang.","p-pro.name":"Professional amaliyot","p-pro.line":"Xavf belgilari, birlashtirish eshiklari, hodisa kartalari va toʻsiqlar.","p-self.name":"Sizga gʻamxoʻrlik","p-self.line":"Charchoq rejimi, oʻzingizga qarash eslatmalari va 4:20.","p-servers.name":"Serverlar va kengayish","p-servers.line":"Umumiy server sozlamalari, rollar va oʻsishni rejalashtirish.","p-livestream.name":"Strim qoʻshimchalari","p-livestream.line":"Twitch chati, shaxsiy emojilar va ochiq jonli koʻrinish."},"words":{"button":"📖 Kasbiy atamalar","h":"📖 Soʻzlar izohi","intro":"AI-gile’da uchraydigan soʻzlar, oddiy tilda: uni yaratish, xavfsiz oʻzgartirish, undan foydalanadigan odamlar uchun ishlab turishini taʼminlash va AI bilan jamoa boʻlib ishlash.","search":"Soʻz qidirish…","none":"Bunday soʻz yoʻq.","close":"Yopish","count":{"one":"{count} ta soʻz","other":"{count} ta soʻz"},"groups":[{"id":"build","name":"🛠️ Yaratish"},{"id":"change","name":"🔀 Xavfsiz oʻzgartirish"},{"id":"run","name":"🛎️ Xizmatni yuritish"},{"id":"team","name":"🤝 Jamoa boʻlib ishlash (va AI bilan)"}],"list":[{"id":"repo","g":"build","word":"Repo","text":"Loyihaning kod papkasi va commitlarning toʻliq tarixi, odatda GitHubda ham saqlanadi.","also":["repozitoriy"]},{"id":"branch","g":"build","word":"Branch","text":"Kodda alohida ish chizigʻi, shunda asosiy versiyaga tegmasdan oʻzgartirishlar kiritish mumkin.","also":["branchlar"]},{"id":"commit","g":"build","word":"Commit","text":"Kodning nima oʻzgargani haqida qisqa izoh bilan saqlangan nusxasi. Unga doim qaytish mumkin.","also":["commitlar"]},{"id":"push","g":"build","word":"Push","text":"Saqlangan nusxalarni (commitlarni) shu kompyuterdan GitHubga yuborish, shunda ular zaxiralanadi va ulashiladi."},{"id":"merge","g":"build","word":"Merge","text":"Branchdagi oʻzgarishlarni asosiy versiyaga qayta qoʻshish."},{"id":"pr","g":"build","word":"Pull request","text":"Branchdagi oʻzgarishlarni tekshirib, asosiy versiyaga qoʻshishni soʻrash.","also":["PR"]},{"id":"refactor","g":"build","word":"Refactor","text":"Kodning vazifasini oʻzgartirmasdan tartibga solish: kichikroq fayllar, aniqroq nomlar, kamroq takrorlash."},{"id":"bug","g":"build","word":"Bug","text":"Ishlashi kerak boʻlganidek ishlamayotgan narsa.","also":["buglar"]},{"id":"test","g":"build","word":"Test","text":"Tugagan ishni qabul qilishdan oldin, soʻralganini bajarayotganini tekshirish uchun sinab koʻrish.","also":["testlar"],"noTip":1},{"id":"qa","g":"build","word":"QA","text":"Quality assurance, yaʼni sifat nazoratining qisqartmasi: biror narsa efirga chiqishidan oldin ishlaydigan avtomatik tekshiruvlar. QA qizil boʻlsa, nimadir oʻtmagan va u tuzatilmaguncha efirga chiqib boʻlmaydi.","also":["sifat nazorati","sifat tekshiruvlari","quality assurance","quality checks"]},{"id":"deploy","g":"change","word":"Deploy","text":"Yangi versiyani ishga tushirish, masalan odamlar foydalanadigan serverga qoʻyish."},{"id":"release","g":"change","word":"Reliz","text":"Birga efirga chiqadigan, nomi bor tayyor ishlar toʻplami, nima oʻzgargani haqida qisqa yozuvlar bilan. 🚀 Relizlar bu yozuvlarni bajarilgan kartalardan yozadi.","also":["relizlar","release","releases"]},{"id":"rollback","g":"change","word":"Orqaga qaytarish","text":"Yangi versiya muammo tugʻdirsa, ishlagan oxirgi versiyaga qaytish. AI-gile’da u har bir oʻzgarishda yozilgan bekor qilish qadamlaridan nazorat roʻyxati tuzadi.","also":["orqaga qaytarildi","rollback","roll back","roll-back","rolled back"]},{"id":"live","g":"change","word":"Efirda","text":"Odamlar foydalanadigan haqiqiy versiya, sinab koʻrish uchun nusxadan farqli oʻlaroq. U yerga qoʻyishni efirga chiqish deymiz. Dasturchilar buni production ham deyishadi.","also":["efirga chiqish","prodakshn","live","production"],"noTip":1},{"id":"change","g":"change","word":"Oʻzgarish","text":"Odamlar tayanadigan narsaga rejalashtirilgan, oldindan yozib qoʻyilgan oʻzgarish: nima, nega, xavf, qachon va qanday bekor qilish. «🔀 Oʻzgarish soʻrash» bilan boshlang.","also":["oʻzgarishlar","oʻzgarish soʻrovi","change","change request","change requests"],"noTip":1},{"id":"risk","g":"change","word":"Xavf","text":"Notoʻgʻri ketishi mumkin boʻlgan narsa, qanchalik ehtimolli va qanchalik yomon boʻlishiga qarab baholangan. ⚠️ Xavflar ularni bitta roʻyxatda saqlaydi, eng yuqori baho tepada, har birida qayta koʻrish sanasi bor.","also":["xavflar","risk","xavflar reyestri","risks","risk register"]},{"id":"chgwin","g":"change","word":"Oʻzgarish oynasi","text":"Oʻzgarishlar efirga chiqishi mumkin boʻlgan vaqtlar, masalan, tinch seshanba oqshomi. Oynadan tashqarida oʻzgarish kartasini yakunlab boʻlmaydi, agar u favqulodda holat boʻlmasa.","also":["oʻzgarish oynalari","change window","change windows"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"Oʻzgarish efirga chiqishidan sal oldin tezkor ovoz berish: tasdiqlashi kerak boʻlgan har bir kishi Go yoki No go deydi. Ular kelishgandagina ish oldinga siljiydi.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Tasdiqlash","text":"Ish boshlanishidan oldin «ha»ni kutish. Doʻstingiz ochgan karta yoki oʻzgarish ✅ Tasdiqlashlar boʻlimida siz uni tasdiqlaguningizcha yoki rad etguningizcha kutadi.","also":["tasdiqlashlar","approval","approvals"]},{"id":"quiettime","g":"change","word":"Sokin vaqt","text":"Hech narsa efirga chiqmaydigan vaqt oraligʻi, masalan, strim, demo yoki tun. Jamoalar ishlash va test qilishda davom etadi, lekin efirga chiqish u tugaguncha kutadi. Boshqa joylarda buni change freeze deyishadi.","also":["sokin vaqtlar","oʻzgarishlarni muzlatish","quiet time","quiet times","change freeze"]},{"id":"service","g":"run","word":"Xizmat","text":"Siz yaratgan va odamlar tayanadigan narsa, masalan, sayt yoki ilova, u ishlab turishi uchun qarab boriladi. «Bu loyiha xizmat» belgisini qoʻying va u nima taklif qilishi, undan kim foydalanishi va kim navbatchi ekanini yozing.","also":["xizmatlar","servis","service","services"]},{"id":"uptime","g":"run","word":"Ishlashni tekshirish","text":"Har bir necha daqiqada xizmatingiz hali ham javob berayotganini avtomatik tekshirish. Agar u ketma-ket bir necha marta oʻtmasa, AI-gile oʻzi hodisa kartasini ochadi.","also":["uptime","uptime check","uptime checks","ishlash vaqti"]},{"id":"statuspage","g":"run","word":"Holat sahifasi","text":"Xizmat ishlayaptimi yoki yoʻqmi (yashil, toʻq sariq yoki qizil) oxirgi yangilanish bilan koʻrsatadigan ochiq sahifa, shunda foydalanuvchilar soʻramasdan oʻzlari tekshira oladi.","also":["holat sahifalari","status page","status pages"]},{"id":"incident","g":"run","word":"Hodisa","text":"Undan foydalanayotgan odamlar uchun hozir buzilgan narsa, masalan, sayt ishlamay qolgan. 🔥 hodisa kartasi navbatsiz oʻtadi: avvalo uni yana ishlatish kerak.","also":["hodisalar","insident","incident","incidents"]},{"id":"major","g":"run","word":"Katta hodisa","text":"Katta hodisa: koʻp odam zarar koʻrgan yoki pul yo maʼlumotlar xavf ostida. Bitta tugma barcha jamoalarni unga qoʻyadi (toʻda), kim navbatchi boʻlsa uygʻotadi va har 30 daqiqada holat yangilanishini soʻraydi.","also":["katta hodisalar","major incident","major incidents"]},{"id":"oncall","g":"run","word":"Navbatchilik","text":"Nimadir buzilganda, hatto tunda ham, javob beradigan odam boʻlish. Har bir xizmatning navbatchi jamoa aʼzosi bor, uning hodisalari uchun birinchi boʻlib u uygʻotiladi.","also":["navbatchi","on call","on-call"]},{"id":"replyby","g":"run","word":"Javob berish muddati","text":"Karta birinchi javobni qancha kutishi mumkin, masalan, hodisa uchun bir soat. Shundan keyin unda qizil soat paydo boʻladi, hech narsa jimgina unutilib ketmasin. Buni response target ham deyishadi.","also":["javob muddati","reply-by time","response target","response targets"]},{"id":"postmortem","g":"run","word":"Hodisa tahlili","text":"Hodisadan keyin qisqa ortga nazar: nima boʻldi, nima yordam berdi va nimani oʻzgartirish kerak, hech kimni ayblamasdan. Usiz hodisani yopib boʻlmaydi. Buni post-mortem ham deyishadi.","also":["post-mortem","post-mortems","postmortem","post-incident review"]},{"id":"problem","g":"run","word":"Muammo","text":"Bir yoki bir nechta hodisa ortidagi yashirin sabab. 🧩 muammo kartasi qayta-qayta takrorlanadigan hodisalarni jamlaydi, shunda sabab topiladi va butunlay tuzatiladi.","also":["muammolar","problem","problems"],"noTip":1},{"id":"rootcause","g":"run","word":"Asosiy sabab","text":"Biror narsa buzilishining haqiqiy sababi, siz koʻrgan nosozlikning oʻzi emas. Asosiy sababni tuzating, shunda hodisa qaytib kelmaydi.","also":["asosiy sabablar","ildiz sabab","root cause","root causes"]},{"id":"workaround","g":"run","word":"Vaqtinchalik yechim","text":"Haqiqiy tuzatish tayyor boʻlguncha ishni davom ettirish yoʻli, masalan, biror narsa qotib qolsa, uni qayta ishga tushirish. U muammo kartasiga yoziladi, shunda hech kim uni qaytadan oʻylab topishi shart emas.","also":["vaqtinchalik yechimlar","workaround","workarounds"]},{"id":"knownerror","g":"run","word":"Maʼlum xato","text":"Sababi tushunilgan va vaqtinchalik yechimi bor, lekin hali tuzatilmagan muammo. 🧩 Maʼlum xatolar ularni roʻyxatda koʻrsatadi, shunda hamma qaytadan qidirmasdan vaqtinchalik yechimdan foydalanadi.","also":["maʼlum xatolar","known error","known errors"]},{"id":"runbook","g":"run","word":"Runbook","text":"Maʼlum turdagi nosozlikni tuzatish uchun qadamma-qadam yoʻriqnoma, shunda u har safar bir xil va tez bajariladi. Katta hodisadan keyin jamoa sizga tasdiqlash uchun runbook taklif qilishi mumkin.","also":["runbooks","qadamma-qadam yoʻriqnoma"]},{"id":"backup","g":"run","word":"Zaxira nusxa","text":"Maʼlumotlaringizning avvalroq saqlangan nusxasi, biror narsa yoʻqolsa yoki buzilsa, unga tayanish uchun. AI-gile har kuni doskalaringizning zaxira nusxasini oladi.","also":["zaxira nusxalar","bekap","backup","backups","back-up","back-ups"]},{"id":"restore","g":"run","word":"Tiklash","text":"Maʼlumotlarni zaxira nusxadan qaytarish. Zaxira nusxa uni tiklash mumkinligini bilgandagina haqiqatan hisobga kiradi, shuning uchun vaqti-vaqti bilan sinab koʻrgan maʼqul.","also":["tiklandi","restore","restored"]},{"id":"backlog","g":"team","word":"Backlog","text":"Hali rejalashtirilmagan gʻoyalar va ishlar. «Bajarilishi kerak»ga oʻtmaguncha, ular ustida ish olib borilmaydi."},{"id":"sprint","g":"team","word":"Sprint","text":"Kelishilgan kartalar toʻplamini tugatish uchun qisqa ish davri (koʻpincha bir-ikki hafta).","also":["sprintlar"]},{"id":"standup","g":"team","word":"Stand-up","text":"Qisqa yigʻilish: jamoaning har bir aʼzosi nima qildi, keyin nima qiladi va nima toʻsqinlik qilmoqda.","also":["standup","stand-uplar"]},{"id":"kanban","g":"team","word":"Kanban","text":"Ustunlari (Bajarilishi kerak, Jarayonda, Bajarildi) boʻlgan doska; ish davomida kartalar chapdan oʻngga oʻtadi."},{"id":"wip","g":"team","word":"WIP limit","text":"Jarayondagi ish: ustunda eng koʻpi bilan nechta karta boʻlishi kerak, shunda jamoa yangisini boshlashdan oldin boshlaganini tugatadi.","also":["WIP"]},{"id":"dod","g":"team","word":"Bajarildi taʼrifi","text":"Jamoaning «tayyor» nimani anglatishi haqidagi qisqa roʻyxati, masalan, test qilingan va tushuntirilgan, karta sizga topshirilishidan oldin. Uning egizagi, Tayyor taʼrifi, karta boshlash uchun yetarlicha aniq boʻlganini aytadi.","also":["Definition of Done","Definition of Ready","Tayyor taʼrifi","DoD","DoR"]},{"id":"testpile","g":"team","word":"Test toʻplami","text":"Siz sinab koʻrishingizni kutayotgan tayyor kartalar, birin-ketin. Birini qabul qiling yoki izoh bilan qaytaring, keyingisi chiqadi.","also":["test toʻplamlari","test pile","test piles"]},{"id":"retro","g":"team","word":"Retro","text":"Jamoa qanday ishlashiga ortga nazar, yaxshiroq qilinadigan bitta narsaga kelishish uchun. AI-gile’da retro jamoaning ish usullariga oʻzgarish taklif qiladi, siz esa Go yoki Hali emas deysiz.","also":["retrolar","retrospektiva","retro","retros","retrospective","retrospectives"]},{"id":"peerreview","g":"team","word":"Hamkasblar tekshiruvi","text":"Ikkinchi juft koʻz: boshqa AI har bir kartaning ishini sizga yetib kelishidan oldin tekshiradi, shunda kamroq xato oʻtib ketadi.","also":["kod tekshiruvi","peer review","code review"]},{"id":"swarm","g":"team","word":"Toʻda","text":"Hamma bir ishga: har bir jamoa boshqa ishini qoldirib, bitta shoshilinch loyihaga u hal boʻlguncha yordam beradi. Bu orada boshqa loyihalar kutadi.","also":["toʻda boʻlib","swarm","swarming"]},{"id":"scrummaster","g":"team","word":"Scrum Master","text":"Ish toʻxtamay borishini kuzatadigan kishi: tiqilib qolgan kartalarni koʻradi, jamoalarni turtib qoʻyadi va sizga nima kutayotganini eslatadi. AI-gile’da buni Lead Scrum Master har bir loyihada qiladi.","also":["Lead Scrum Master","skram-master"]},{"id":"agent","g":"team","word":"Agent","text":"Vazifa ustida mustaqil ishlaydigan AI: kodni oʻqiydi, oʻzgartirishlar kiritadi, tekshiruvlarni ishga tushiradi va hisobot beradi.","also":["agentlar"]},{"id":"token","g":"team","word":"Token","text":"AI sarfi hisoblanadigan birlik: taxminan oʻqilgan yoki yozilgan matnning bir necha harfi. Token kam boʻlsa, tarifingizdan koʻproq qoladi.","also":["tokenlar"]},{"id":"hook","g":"team","word":"Hook","text":"Belgilangan paytda oʻzi ishlaydigan kichik buyruq, masalan AI sessiyasi boshlanganda, shunda jamoa izohlaringizni eshitadi.","also":["hooklar"]}]}};
